// 1. Obter clientes recebidos pelo Webhook
const webhookItem = $('Webhook - Clientes').first();
const rawBody = webhookItem.json.body ?? webhookItem.json;
const clientes = Array.isArray(rawBody) ? rawBody : (rawBody.clientes ?? rawBody.data?.clientes ?? []);

if (!Array.isArray(clientes) || clientes.length === 0) {
  throw new Error('Nenhum cliente válido recebido no payload. Formato esperado: { "clientes": [...] }');
}

// 2. Obter base de investimentos lida do docs/data.csv via nó HTTP Request
let csvText = '';
try {
  const httpItem = $('Carregar data.csv').first();
  if (typeof httpItem.json.data === 'string') {
    csvText = httpItem.json.data;
  } else if (typeof httpItem.json === 'string') {
    csvText = httpItem.json;
  }
} catch (err) {}

// Fallback robusto caso haja instabilidade de rede ao acessar o GitHub Pages
if (!csvText || !csvText.includes('perfil')) {
  csvText = `perfil,produto,minimo,rentabilidade
Conservador,Poupança,100,6.2%
Conservador,CDB Liquidez Diária,1000,12.5%
Conservador,Tesouro Selic,500,13.0%
Moderado,CDB Prefixado,1000,14.0%
Moderado,Fundo Multimercado,5000,16.0%
Moderado,Tesouro IPCA+,1000,IPCA+6.0%
Arrojado,Ações ETF,500,Variável
Arrojado,Fundo de Ações,10000,Variável
Arrojado,Criptomoedas,100,Variável`;
}

// 3. Parser do CSV
const linhasCsv = csvText.trim().split(/\r?\n/);
const catalogoInvestimentos = [];
for (let i = 1; i < linhasCsv.length; i++) {
  const partes = linhasCsv[i].split(',').map(s => s.trim());
  if (partes.length >= 4) {
    catalogoInvestimentos.push({
      perfil: partes[0],
      produto: partes[1],
      minimo: parseFloat(partes[2]) || 0,
      rentabilidade: partes[3]
    });
  }
}

// Funções auxiliares de sanitização e formatação
function extrairSaldoNumerico(valor) {
  if (typeof valor === 'number') return valor;
  if (!valor) return 0;
  const limpo = String(valor).replace(/[^\d,.-]/g, '').replace(/\./g, '').replace(',', '.');
  const num = parseFloat(limpo);
  return isNaN(num) ? 0 : num;
}

function formatarMoeda(num) {
  return num.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

// 4. Cruzamento de dados de clientes com opções de investimento
const recomendacoes = clientes.map(cliente => {
  const nomeCompleto = String(cliente.nome ?? 'Investidor(a)').trim();
  const primeiroNome = nomeCompleto.split(/\s+/)[0];
  const perfil = String(cliente.perfil ?? '').trim();
  const saldoNum = extrairSaldoNumerico(cliente.saldo);
  const saldoFormatado = formatarMoeda(saldoNum);

  // Produtos do perfil do cliente
  const produtosDoPerfil = catalogoInvestimentos.filter(
    p => p.perfil.toLowerCase() === perfil.toLowerCase()
  );

  // Produtos elegíveis pelo saldo
  const produtosElegiveis = produtosDoPerfil.filter(p => saldoNum >= p.minimo);

  let produtoDestaque = null;
  let mensagem = '';

  const listaFormatada = produtosElegiveis.length > 0
    ? produtosElegiveis.map(p => `• ${p.produto} (Aporte mín.: ${formatarMoeda(p.minimo)} | Rentabilidade: ${p.rentabilidade})`).join('\n')
    : `• Nenhum produto atinge o mínimo no momento. Sugerimos aportes graduais para a opção de entrada: ${produtosDoPerfil[0]?.produto} (mín. ${formatarMoeda(produtosDoPerfil[0]?.minimo || 0)}).`;

  if (perfil.toLowerCase() === 'conservador') {
    produtoDestaque = produtosElegiveis.find(p => p.produto.includes('CDB Liquidez') || p.produto.includes('Tesouro')) || produtosDoPerfil[0];
    mensagem = `Olá, ${primeiroNome}!\n` +
      `Identificamos seu perfil Conservador com saldo disponível de ${cliente.saldo || saldoFormatado}.\n` +
      `Para quem prioriza segurança, previsibilidade e reserva de emergência com liquidez diária, ` +
      `selecionamos as seguintes opções adequadas à sua carteira:\n\n` +
      `${listaFormatada}\n\n` +
      `💡 Destaque da Assessoria: ${produtoDestaque?.produto} com rentabilidade de ${produtoDestaque?.rentabilidade}.\n` +
      `Uma excelente alternativa para proteger seu patrimônio com ganhos acima da poupança tradicional.\n\n` +
      `*Aviso legal: Rentabilidade passada não é garantia de resultados futuros. Consulte sempre seu assessor.*`;
  } else if (perfil.toLowerCase() === 'moderado') {
    produtoDestaque = produtosElegiveis.find(p => p.produto.includes('Tesouro IPCA+') || p.produto.includes('CDB Prefixado')) || produtosDoPerfil[0];
    mensagem = `Olá, ${primeiroNome}!\n` +
      `Identificamos seu perfil Moderado com saldo disponível de ${cliente.saldo || saldoFormatado}.\n` +
      `Seu perfil busca a combinação ideal entre segurança patrimonial e ganhos reais acima da inflação no médio prazo.\n\n` +
      `${listaFormatada}\n\n` +
      `💡 Destaque da Assessoria: ${produtoDestaque?.produto} com rentabilidade de ${produtoDestaque?.rentabilidade}.\n` +
      `A diversificação entre crédito privado e títulos indexados ao IPCA potencializa sua rentabilidade mantendo o risco equilibrado.\n\n` +
      `*Aviso legal: Rentabilidade passada não é garantia de resultados futuros. Avalie seus objetivos de médio prazo.*`;
  } else if (perfil.toLowerCase() === 'arrojado') {
    produtoDestaque = produtosElegiveis.find(p => p.produto.includes('Fundo de Ações') || p.produto.includes('Ações ETF')) || produtosDoPerfil[0];
    mensagem = `Olá, ${primeiroNome}!\n` +
      `Identificamos seu perfil Arrojado com saldo disponível de ${cliente.saldo || saldoFormatado}.\n` +
      `Investidores arrojados toleram volatilidade em troca de expressivo potencial de valorização no longo prazo.\n\n` +
      `${listaFormatada}\n\n` +
      `💡 Destaque da Assessoria: ${produtoDestaque?.produto} (Rentabilidade: ${produtoDestaque?.rentabilidade}).\n` +
      `Alocar em renda variável e fundos possibilita capturar o crescimento das maiores empresas do mercado.\n\n` +
      `*Aviso legal: Ativos de renda variável possuem oscilação de cota e risco de perda. Mantenha foco no longo prazo.*`;
  } else {
    mensagem = `Olá, ${primeiroNome}! Confirmamos seu saldo de ${cliente.saldo}. Favor entrar em contato para atualizar seu questionário de perfil de investidor.`;
  }

  return {
    nome: cliente.nome,
    email: cliente.email,
    perfil: perfil,
    saldo_original: cliente.saldo,
    saldo_numerico: saldoNum,
    produto_destaque: produtoDestaque ? produtoDestaque.produto : null,
    rentabilidade_destaque: produtoDestaque ? produtoDestaque.rentabilidade : null,
    total_produtos_elegiveis: produtosElegiveis.length,
    produtos_elegiveis: produtosElegiveis,
    mensagem: mensagem
  };
});

return [{ json: { recomendacoes } }];

const data = $input.first().json;
const recomendacoes = data.recomendacoes || [];

const contagemPerfis = { Conservador: 0, Moderado: 0, Arrojado: 0, Outros: 0 };
let patrimonioTotal = 0;

for (const r of recomendacoes) {
  const p = (r.perfil || '').toLowerCase();
  if (p === 'conservador') contagemPerfis.Conservador++;
  else if (p === 'moderado') contagemPerfis.Moderado++;
  else if (p === 'arrojado') contagemPerfis.Arrojado++;
  else contagemPerfis.Outros++;
  patrimonioTotal += (r.saldo_numerico || 0);
}

return [{
  json: {
    status: 'sucesso',
    tipo_execucao: 'MVP - Templates Dinâmicos por Perfil',
    timestamp: new Date().toISOString(),
    total_processado: recomendacoes.length,
    distribuicao_perfis: contagemPerfis,
    patrimonio_total_analisado: patrimonioTotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }),
    resultados: recomendacoes
  }
}];
